const {chromium}=require('playwright'),fs=require('fs'),path=require('path'),http=require('http'),assert=require('assert/strict'),crypto=require('crypto');
const repo=process.env.INK_REPO_ROOT||process.cwd(),root=process.env.INK_QA_BASELINE||repo,prefix=process.env.INK_QA_BASELINE?'before':'after',dir=path.join(repo,'working/evidence/ink-ui-sup08-11-20261002');fs.mkdirSync(dir,{recursive:true});
(async()=>{const fontRoot=process.env.INK_QA_FONT_ROOT,server=http.createServer((req,res)=>{const url=decodeURIComponent(req.url.split('?')[0]);let p=url.startsWith('/qa-fonts/')?path.join(fontRoot,url.slice(10)):path.join(root,url);if(fs.existsSync(p)&&fs.statSync(p).isDirectory())p=path.join(p,'index.html');if(!fs.existsSync(p)){res.writeHead(404);res.end();return;}res.setHeader('Content-Type',({'.js':'text/javascript','.mjs':'text/javascript','.css':'text/css','.html':'text/html','.json':'application/json','.woff2':'font/woff2','.svg':'image/svg+xml'})[path.extname(p)]||'application/octet-stream');res.end(fs.readFileSync(p));});await new Promise(r=>server.listen(8766,'127.0.0.1',r));const packed=(await import(process.env.INK_QA_CHROMIUM_MODULE)).default,browser=await chromium.launch({executablePath:await packed.executablePath(),headless:true,args:[...packed.args.filter(x=>!/gpu|use-gl|use-angle/.test(x)),'--disable-gpu','--disable-software-rasterizer']}),page=await browser.newPage({viewport:{width:1280,height:1024},deviceScaleFactor:1}),cdp=await page.context().newCDPSession(page),errors=[],loaded=[],jobs=[],r={baseline:fs.readFileSync(path.join(repo,'../sup-baseline-sha.txt'),'utf8').trim(),source:prefix,browser:browser.version(),tools:[],checks:[],snapshots:[]};
page.on('pageerror',e=>errors.push(String(e)));page.on('dialog',d=>d.accept());page.on('response',res=>{if(res.status()>=400)errors.push(res.status()+' '+res.url());if(new URL(res.url()).pathname.startsWith('/product/source/'))jobs.push((async()=>{let p=path.join(root,new URL(res.url()).pathname);if(fs.statSync(p).isDirectory())p=path.join(p,'index.html');const b=await res.body();loaded.push({url:res.url(),sha256:crypto.createHash('sha256').update(b).digest('hex'),matches:b.equals(fs.readFileSync(p))});})().catch(e=>errors.push(String(e))));});
const settle=async()=>{await page.evaluate(async()=>{await document.fonts.ready;await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));});await page.waitForTimeout(100);};const check=(name,ok,data)=>{r.checks.push({name,ok,data});assert(ok,name+': '+JSON.stringify(data));};
async function capture(name){await settle();await page.mouse.move(500,700);await settle();const ss=await cdp.send('Page.captureScreenshot',{format:'png',fromSurface:false,captureBeyondViewport:false});fs.writeFileSync(path.join(dir,prefix+'-options-'+name+'.png'),Buffer.from(ss.data,'base64'));r.snapshots.push(name);}
async function activate(tool){await page.evaluate(tool=>{if(['select','eraser','pan'].includes(tool))INK_APP.setTool(tool);else INK_UI_B.activateTool(tool);},tool);await settle();return await page.evaluate(()=>{const h=document.querySelector('#contextualOptions'),visible=e=>e.checkVisibility({visibilityProperty:true})&&e.getClientRects().length;return{context:h.dataset.contextTool,mode:h.dataset.contextMode,controls:[...h.querySelectorAll('input,select,button')].filter(visible).map(e=>({id:e.id,key:e.dataset.uiBOption||e.dataset.uiBBrushOption||e.dataset.uiBNativeOption||e.dataset.uiBNativeAction||e.dataset.editProxy||e.dataset.shape||e.dataset.eraserMode,value:e.value,label:e.closest('label')?.innerText||e.innerText,disabled:e.disabled,type:e.type,rect:e.getBoundingClientRect().toJSON()})),tool:INK_APP.tool,raster:INK_UI_B.raster.activeTool(),ids:[...document.querySelectorAll('[id]')].map(e=>e.id).filter((id,i,a)=>a.indexOf(id)!==i)};});}
try{await page.goto('http://127.0.0.1:8766/product/source/',{waitUntil:'networkidle'});await page.waitForFunction(()=>window.INK_APP&&window.INK_UI_B);await page.locator('[data-application-menu-trigger="file"]').click();await page.locator('[data-file-command="new"]').click();await settle();await page.evaluate(()=>INK_APP.ensureSpatialIndex());await activate('shape:rect');await page.mouse.move(330,350);await page.mouse.down();await page.mouse.move(430,440,{steps:8});await page.mouse.up();r.beforeLasso=await page.evaluate(()=>({dirty:INK_APP.spatialDirty,objectCount:INK_APP.layer().objects.length,indexCount:INK_APP.spatialIndex.items.length}));await activate('lasso');await page.mouse.move(300,300);await page.mouse.down();for(const [x,y]of [[500,300],[500,480],[300,480],[300,300]])await page.mouse.move(x,y,{steps:6});await page.mouse.up();r.selectedBeforeRefresh=await page.evaluate(()=>INK_APP.selection.length);await page.evaluate(()=>INK_APP.refreshAll());await page.mouse.move(300,300);await page.mouse.down();for(const [x,y]of [[500,300],[500,480],[300,480],[300,300]])await page.mouse.move(x,y,{steps:6});await page.mouse.up();r.selectedAfterRefresh=await page.evaluate(()=>INK_APP.selection.length);await capture('native-spatial-probe');}catch(e){r.failure=String(e);process.exitCode=1;console.error(e);}
r.errors=errors;r.loaded=loaded;fs.writeFileSync(path.join(dir,prefix+'-spatial-probe.json'),JSON.stringify(r,null,2));console.log(JSON.stringify({prefix,toolCount:r.tools.length,checks:r.checks.length,failure:r.failure,errors}));await browser.close();server.close();})();
